import datetime
import calendar


def parse_field(field: str, min_val: int, max_val: int, name_map: dict = None) -> set:
    """Parse a single cron field into a set of valid values."""
    result = set()

    # Split by comma
    parts = field.split(',')
    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError(f"Empty field component")

        # Handle step notation
        step = 1
        if '/' in part:
            part, step_str = part.split('/')
            step_str = step_str.strip()
            if not step_str:
                raise ValueError("Empty step value")
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")

        # Handle wildcard or range
        if part == '*':
            values = range(min_val, max_val + 1)
        elif '-' in part:
            range_parts = part.split('-')
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range: {part}")
            start_str, end_str = range_parts
            try:
                start = parse_value(start_str.strip(), name_map)
                end = parse_value(end_str.strip(), name_map)
            except ValueError as e:
                raise ValueError(f"Invalid range values in {part}: {e}")
            if start > end:
                raise ValueError(f"Range start ({start}) > end ({end}) in {part}")
            values = range(start, end + 1)
        else:
            # Single value
            value = parse_value(part, name_map)
            values = [value]

        # Apply step and add to result
        for v in values:
            if v < min_val or v > max_val:
                raise ValueError(f"Value {v} out of range [{min_val}, {max_val}]")
            if (v - min_val) % step == 0:
                result.add(v)

    if not result:
        raise ValueError(f"No valid values for field: {field}")

    return result


def parse_value(value_str: str, name_map: dict = None) -> int:
    """Parse a single value, handling names if a name_map is provided."""
    value_str = value_str.strip()

    # Check if it's a name
    if name_map:
        upper_value = value_str.upper()
        if upper_value in name_map:
            return name_map[upper_value]

    # Try to parse as integer
    try:
        return int(value_str)
    except ValueError:
        raise ValueError(f"Invalid value: {value_str}")


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Get the next fire time for a cron expression.

    Args:
        expr: Standard 5-field cron expression
        after: Datetime to find the next fire time after

    Returns:
        Datetime representing the next fire time

    Raises:
        ValueError: If the expression is invalid or no match found within 5 years
    """
    # Parse the cron expression
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError(f"Cron expression must have exactly 5 fields, got {len(parts)}")

    minute_str, hour_str, dom_str, month_str, dow_str = parts

    # Define mappings and ranges
    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }

    day_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    # Parse each field
    try:
        minutes = parse_field(minute_str, 0, 59)
        hours = parse_field(hour_str, 0, 23)
        days_of_month = parse_field(dom_str, 1, 31)
        months = parse_field(month_str, 1, 12, month_names)
        days_of_week = parse_field(dow_str, 0, 7, day_names)
    except ValueError as e:
        raise ValueError(f"Invalid cron field: {e}")

    # Normalize days_of_week: 7 should be treated as 0 (Sunday)
    normalized_days_of_week = {d % 7 for d in days_of_week}

    # Determine if DOM and DOW are restricted
    dom_restricted = days_of_month != set(range(1, 32))
    dow_restricted = normalized_days_of_week != {0, 1, 2, 3, 4, 5, 6}

    # Start from the next minute after 'after'
    current_dt = after.replace(second=0, microsecond=0)
    current_dt += datetime.timedelta(minutes=1)

    # Limit search to 5 years
    max_dt = after.replace(year=after.year + 5, month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
    if max_dt <= after:
        max_dt = after + datetime.timedelta(days=5*366)

    # Search through potential dates
    max_year = after.year + 5
    max_day = after + datetime.timedelta(days=5*366)

    while current_dt <= max_day:
        year = current_dt.year
        month = current_dt.month
        day = current_dt.day

        # Check if month matches
        if month not in months:
            current_dt += datetime.timedelta(days=1)
            continue

        # Check day of month and day of week
        current_dow = current_dt.weekday()  # Monday=0, Sunday=6
        cron_dow = (current_dow + 1) % 7   # Convert to Sunday=0, Saturday=6

        # Vixie cron: if both DOM and DOW are restricted, match if either matches
        # Otherwise, both must match
        dom_match = day in days_of_month
        dow_match = cron_dow in normalized_days_of_week

        if dom_restricted and dow_restricted:
            # Either DOM or DOW must match
            if not (dom_match or dow_match):
                current_dt += datetime.timedelta(days=1)
                continue
        else:
            # Both must match
            if not (dom_match and dow_match):
                current_dt += datetime.timedelta(days=1)
                continue

        # Now check hour and minute
        for h in sorted(hours):
            start_h = current_dt.hour
            # If we've moved to the next day, reset to start hour
            if h < start_h and current_dt.day == day:
                continue

            for m in sorted(minutes):
                # Skip if minute is not later than current minute on the same hour
                if h == start_h and m <= current_dt.minute:
                    continue

                # Create candidate datetime
                candidate = datetime.datetime(year, month, day, h, m, 0, 0)

                # Must be strictly after 'after'
                if candidate > after:
                    return candidate

        # Move to next day
        current_dt += datetime.timedelta(days=1)

    raise ValueError("No match found within 5 years")
