from collections import OrderedDict


def flatten(obj, sep="."):
    """
    Turns nested dicts and lists into a flat dict with path keys.

    - dict keys are joined with sep
    - list items use their index (a.0.b)
    - empty dicts and empty lists are kept as leaf values ({"a": {}} -> {"a": {}})
    - any other value is a leaf
    - top-level object must be a dict (else TypeError)
    - keys must be strings that don't contain sep (else ValueError)
    - order: depth-first, in input's order
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = OrderedDict()

    def _flatten(current, path_parts):
        # If current is a dict, process its items
        if isinstance(current, dict):
            for key, value in current.items():
                # Check key type and content
                if not isinstance(key, str):
                    raise ValueError(f"Dict key must be a string, got {type(key).__name__}")
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")

                new_path = path_parts + [key]
                # If value is a dict or list, recurse; otherwise, it's a leaf
                if isinstance(value, (dict, list)) and not isinstance(value, (str, bytes)):
                    _flatten(value, new_path)
                else:
                    # It's a leaf value (including empty dict/list)
                    result[sep.join(new_path)] = value
        # If current is a list, process its items
        elif isinstance(current, list):
            for i, item in enumerate(current):
                new_path = path_parts + [str(i)]
                # If item is a dict or list, recurse; otherwise, it's a leaf
                if isinstance(item, (dict, list)) and not isinstance(item, (str, bytes)):
                    _flatten(item, new_path)
                else:
                    # It's a leaf value (including empty dict/list)
                    result[sep.join(new_path)] = item
        # For other types (str, int, etc.), treat as leaf and do nothing here
        # (we handle leaf values in the parent recursive calls)

    _flatten(obj, [])
    return result


