def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenizer
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        elif c.isdigit() or c == '.':
            # Number token
            j = i
            has_dot = c == '.'
            if not has_dot:
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                if j < len(expr) and expr[j] == '.':
                    has_dot = True
                    j += 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
            else:
                # Starts with dot, so it's a decimal
                j = i + 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
            num_str = expr[i:j]
            try:
                if '.' in num_str:
                    tokens.append(('NUM', float(num_str)))
                else:
                    tokens.append(('NUM', int(num_str)))
            except ValueError:
                raise SyntaxError(f"Invalid number: {num_str}")
            i = j
        elif c.isalpha() or c == '_':
            # Identifier or keyword
            j = i
            while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            ident = expr[i:j]
            if ident in ('true', 'false'):
                raise SyntaxError("Boolean literals are not supported; use 1 and 0")
            tokens.append(('ID', ident))
            i = j
        elif c == '?' or c == ':' or c == '|' or c == '&' or c == '!' or c == '<' or c == '>' or c == '=' or c == '+' or c == '-' or c == '*' or c == '/' or c == '%' or c == '^' or c == '(' or c == ')' or c == ',':
            # Operator or delimiter
            # Check for compound operators first
            if c == '|' and i + 1 < len(expr) and expr[i+1] == '|':
                tokens.append(('OP', '||'))
                i += 2
                continue
            elif c == '&' and i + 1 < len(expr) and expr[i+1] == '&':
                tokens.append(('OP', '&&'))
                i += 2
                continue
            elif c == '!' and i + 1 < len(expr) and expr[i+1] == '=':
                tokens.append(('OP', '!='))
                i += 2
                continue
            elif c == '=' and i + 1 < len(expr) and expr[i+1] == '=':
                tokens.append(('OP', '=='))
                i += 2
                continue
            elif c == '<' and i + 1 < len(expr) and expr[i+1] == '=':
                tokens.append(('OP', '<='))
                i += 2
                continue
            elif c == '>' and i + 1 < len(expr) and expr[i+1] == '=':
                tokens.append(('OP', '>='))
                i += 2
                continue
            elif c == '<' and i + 1 < len(expr) and expr[i+1] == '>':
                # This is not a valid operator, raise error
                raise SyntaxError("Invalid operator '<>'")
            elif c == '<':
                tokens.append(('OP', '<'))
                i += 1
                continue
            elif c == '>':
                tokens.append(('OP', '>'))
                i += 1
                continue
            elif c == '=':
                raise SyntaxError("Lone '=' is not allowed")
            elif c == '+':
                tokens.append(('OP', '+'))
                i += 1
                continue
            elif c == '-':
                tokens.append(('OP', '-'))
                i += 1
                continue
            elif c == '*':
                tokens.append(('OP', '*'))
                i += 1
                continue
            elif c == '/':
                tokens.append(('OP', '/'))
                i += 1
                continue
            elif c == '%':
                tokens.append(('OP', '%'))
                i += 1
                continue
            elif c == '^':
                tokens.append(('OP', '^'))
                i += 1
                continue
            elif c == '!':
                tokens.append(('OP', '!'))
                i += 1
                continue
            elif c == '?':
                tokens.append(('OP', '?'))
                i += 1
                continue
            elif c == ':':
                tokens.append(('OP', ':'))
                i += 1
                continue
            elif c == '(':
                tokens.append(('LPAREN', '('))
                i += 1
                continue
            elif c == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
                continue
            elif c == ',':
                tokens.append(('COMMA', ','))
                i += 1
                continue
            else:
                raise SyntaxError(f"Invalid token: {c}")
        else:
            raise SyntaxError(f"Invalid token: {c}")

    if not tokens:
        raise SyntaxError("Empty input")

    # Parser: recursive descent
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        if pos >= len(tokens):
            raise SyntaxError("Unexpected end of input")
        t = tokens[pos]
        pos += 1
        return t

    def expect(tok_type, val=None):
        t = peek()
        if t is None:
            raise SyntaxError("Unexpected end of input")
        if t[0] != tok_type or (val is not None and t[1] != val):
            raise SyntaxError(f"Expected {tok_type} {val}, got {t}")
        return consume()

    def parse_expr():
        return parse_cond_expr()

    def parse_cond_expr():
        expr = parse_logical_or_expr()
        if peek() and peek()[0] == 'OP' and peek()[1] == '?':
            consume()  # '?'
            left_expr = expr
            then_expr = parse_expr()  # Recursively parse expr for then branch
            expect('OP', ':')
            else_expr = parse_cond_expr()  # Right-associative: parse rest of conditional
            return ('COND', left_expr, then_expr, else_expr)
        return expr

    def parse_logical_or_expr():
        left = parse_logical_and_expr()
        while peek() and peek()[0] == 'OP' and peek()[1] == '||':
            consume()
            right = parse_logical_and_expr()
            left = ('OR', left, right)
        return left

    def parse_logical_and_expr():
        left = parse_comparison_expr()
        while peek() and peek()[0] == 'OP' and peek()[1] == '&&':
            consume()
            right = parse_comparison_expr()
            left = ('AND', left, right)
        return left

    def parse_comparison_expr():
        left = parse_add_expr()
        # Non-associative: only one comparison allowed
        if peek() and peek()[0] == 'OP' and peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = consume()[1]
            right = parse_add_expr()
            if peek() and peek()[0] == 'OP' and peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
                raise SyntaxError("Chained comparison is not allowed")
            return ('CMP', op, left, right)
        elif peek() and peek()[0] == 'OP' and peek()[1] in ('==', '!=', '<', '<=', '>', '>='):
            raise SyntaxError("Comparison without right operand")
        return left

    def parse_add_expr():
        left = parse_mul_expr()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_mul_expr()
            left = ('BINOP', op, left, right)
        return left

    def parse_mul_expr():
        left = parse_unary_expr()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '/', '%'):
            op = consume()[1]
            right = parse_unary_expr()
            left = ('BINOP', op, left, right)
        return left

    def parse_unary_expr():
        if peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-', '!'):
            op = consume()[1]
            operand = parse_unary_expr()
            return ('UNARY', op, operand)
        return parse_power_expr()

    def parse_power_expr():
        base = parse_atom()
        if peek() and peek()[0] == 'OP' and peek()[1] == '^':
            consume()
            # Right-associative: parse power_expr recursively, but we want to parse unary_expr on the right
            exponent = parse_unary_expr()
            return ('POW', base, exponent)
        return base

    def parse_atom():
        t = peek()
        if t is None:
            raise SyntaxError("Unexpected end of input")

        if t[0] == 'NUM':
            return consume()

        if t[0] == 'ID':
            name = consume()[1]
            # Check if it's a function call
            if peek() and peek()[0] == 'LPAREN':
                consume()  # '('
                args = []
                if peek() and peek()[0] != 'RPAREN':
                    args.append(parse_expr())
                    while peek() and peek()[0] == 'COMMA':
                        consume()
                        args.append(parse_expr())
                expect('RPAREN', ')')
                # Built-in functions: min, max, abs
                if name == 'abs':
                    if len(args) != 1:
