                    return ('CALL', 'abs', args)
                elif name == 'min':
                    if len(args) < 1:
                        raise SyntaxError("min() expects at least 1 argument")
                    return ('CALL', 'min', args)
                elif name == 'max':
                    if len(args) < 1:
                        raise SyntaxError("max() expects at least 1 argument")
                    return ('CALL', 'max', args)
                else:
                    # User-defined functions are not supported; unknown function
                    raise NameError(f"Unknown function: {name}")
            else:
                # Identifier: look up in env
                if name not in env:
                    raise NameError(f"Unknown variable: {name}")
                return ('VAR', name)

        if t[0] == 'LPAREN':
            consume()
            result = parse_expr()
            expect('RPAREN', ')')
            return result

        raise SyntaxError(f"Unexpected token: {t}")

    ast = parse_expr()

    if pos < len(tokens):
        raise SyntaxError("Unexpected trailing tokens")

    # Evaluator
    def eval_ast(node, env):
        if node is None:
            raise SyntaxError("Empty expression")

        if isinstance(node, tuple):
            op = node[0]
            if op == 'NUM':
                return node[1]
            elif op == 'VAR':
                name = node[1]
                if name not in env:
                    raise NameError(f"Unknown variable: {name}")
                return env[name]
            elif op == 'BINOP':
                _, op_str, left, right = node
                l = eval_ast(left, env)
                r = eval_ast(right, env)
                if op_str == '+':
                    return l + r
                elif op_str == '-':
                    return l - r
                elif op_str == '*':
                    return l * r
                elif op_str == '/':
                    if r == 0:
                        raise ZeroDivisionError("division by zero")
                    # For two ints, if exact division, return int, else float
                    if isinstance(l, int) and isinstance(r, int):
                        res = l / r
                        if res == int(res):
                            return int(res)
                        return res
                    return l / r
                elif op_str == '%':
                    if r == 0:
                        raise ZeroDivisionError("modulo by zero")
                    return l % r
                else:
                    raise SyntaxError(f"Unknown operator: {op_str}")
            elif op == 'UNARY':
                _, op_str, operand = node
                val = eval_ast(operand, env)
                if op_str == '+':
                    return val
                elif op_str == '-':
                    return -val
                elif op_str == '!':
                    return 1 if val == 0 else 0
                else:
                    raise SyntaxError(f"Unknown unary operator: {op_str}")
            elif op == 'POW':
                _, base, exponent = node
                b = eval_ast(base, env)
                e = eval_ast(exponent, env)
                return b ** e
            elif op == 'COND':
                _, cond_expr, then_expr, else_expr = node
                cond_val = eval_ast(cond_expr, env)
                # True when non-zero
                if cond_val != 0:
                    return eval_ast(then_expr, env)
                else:
                    return eval_ast(else_expr, env)
            elif op == 'OR':
                _, left, right = node
                l = eval_ast(left, env)
                if l != 0:
                    return 1
                else:
                    # Short-circuit: evaluate right
                    r = eval_ast(right, env)
                    return 1 if r != 0 else 0
            elif op == 'AND':
                _, left, right = node
                l = eval_ast(left, env)
                if l == 0:
                    return 0
                else:
                    r = eval_ast(right, env)
                    return 1 if r != 0 else 0
            elif op == 'CMP':
                _, op_str, left, right = node
                l = eval_ast(left, env)
                r = eval_ast(right, env)
                if op_str == '==':
                    return 1 if l == r else 0
                elif op_str == '!=':
                    return 1 if l != r else 0
                elif op_str == '<':
                    return 1 if l < r else 0
                elif op_str == '<=':
                    return 1 if l <= r else 0
                elif op_str == '>':
                    return 1 if l > r else 0
                elif op_str == '>=':
                    return 1 if l >= r else 0
                else:
                    raise SyntaxError(f"Unknown comparison: {op_str}")
            elif op == 'CALL':
                _, func, args = node
                arg_values = [eval_ast(a, env) for a in args]
                if func == 'abs':
                    return abs(arg_values[0])
                elif func == 'min':
                    return min(arg_values)
                elif func == 'max':
                    return max(arg_values)
                else:
                    raise NameError(f"Unknown function: {func}")
        raise SyntaxError(f"Unknown AST node: {node}")

    return eval_ast(ast, env)
