from collections import defaultdict
import heapq

def route(grid: list[str]) -> tuple[int, str] | None:
    # Input validation
    if not grid:
        raise ValueError("Grid is empty")

    n = len(grid)
    m = len(grid[0])

    # Check for ragged rows
    for row in grid:
        if len(row) != m:
            raise ValueError("Ragged grid: rows have different lengths")

    # Count S, E, and letters
    start_pos = None
    end_pos = None
    letter_positions = defaultdict(list)
    valid_chars = set('.#SE')
    valid_chars.update('0123456789')
    valid_chars.update('abcdefghijklmnopqrstuvwxyz')

    for i in range(n):
        for j in range(m):
            ch = grid[i][j]
            if ch == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple start positions 'S'")
                start_pos = (i, j)
            elif ch == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple end positions 'E'")
                end_pos = (i, j)
            elif ch.islower():
                if ch in valid_chars:
                    valid_chars.discard(ch)
                letter_positions[ch].append((i, j))
            elif ch not in valid_chars:
                raise ValueError(f"Unknown character '{ch}' in grid")

    # Check S and E exist
    if start_pos is None:
        raise ValueError("No start position 'S' found")
    if end_pos is None:
        raise ValueError("No end position 'E' found")

    # Check letter positions: each letter must appear 0 or 2 times
    for letter, positions in letter_positions.items():
        if len(positions) != 2:
            raise ValueError(f"Letter '{letter}' appears {len(positions)} times (must be 0 or 2)")

    # Direction definitions with move names and order (D < L < R < T < U)
    # The move ordering is D < L < R < T < U, so we sort directions accordingly
    # Note: In the final lexicographic ordering, moves are strings where each char is a move
    # The move order for tie-breaking: D < L < R < T < U
    # So when we have equal costs, we choose the lexicographically smallest move string
    directions = [
        ('D', 1, 0),    # Down: increase row
        ('L', 0, -1),   # Left: decrease column
        ('R', 0, 1),    # Right: increase column
        ('T', 0, 0),    # Teleport: special move
        ('U', -1, 0)    # Up: decrease row
    ]

    # Precompute teleport pairs
    teleport_map = {}
    for letter, positions in letter_positions.items():
        pos1, pos2 = positions
        teleport_map[pos1] = pos2
        teleport_map[pos2] = pos1

    # Cost function for a cell
    def cell_cost(cell):
        ch = grid[cell[0]][cell[1]]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1  # teleport pads cost 1
        else:
            return float('inf')

    # Dijkstra with lexicographic tie-breaking for moves
    # State: (cost, move_string, row, col)
    # We use a priority queue where we compare first by cost, then by move_string lexicographically

    start_i, start_j = start_pos
    end_i, end_j = end_pos

    # dist[(i,j)] = (min_cost, lexicographically_smallest_moves_to_reach_with_min_cost)
    dist = {}
    # Priority queue: (cost, move_string, i, j)
    pq = [(0, "", start_i, start_j)]
    dist[(start_i, start_j)] = (0, "")

    while pq:
        cost, moves, i, j = heapq.heappop(pq)

        # Skip if we've found a better path to this cell
        if (i, j) in dist:
            best_cost, best_moves = dist[(i, j)]
            if cost > best_cost:
                continue
            if cost == best_cost and moves > best_moves:
                continue

        # Check if we reached the end
        if (i, j) == (end_i, end_j):
            return (cost, moves)

        # Generate neighbors
        # Normal moves (D, L, R, U) - T is handled separately as teleport
        for move_name, di, dj in directions:
            # Skip teleport move in normal iteration
            if move_name == 'T':
                continue

            ni, nj = i + di, j + dj

            # Check bounds
            if 0 <= ni < n and 0 <= nj < m:
                # Check if it's a wall
                if grid[ni][nj] == '#':
                    continue

                # Calculate new cost and moves
                cell_c = cell_cost((ni, nj))
                new_cost = cost + cell_c
                new_moves = moves + move_name

                # Update if we found a better path
                state = (ni, nj)
                if state not in dist:
                    dist[state] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, ni, nj))
                else:
                    existing_cost, existing_moves = dist[state]
                    if new_cost < existing_cost:
                        dist[state] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, ni, nj))
                    elif new_cost == existing_cost and new_moves < existing_moves:
                        dist[state] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, ni, nj))

        # Teleport move (T)
        if grid[i][j].islower():
            # Find the teleport destination
            teleport_pos = teleport_map.get((i, j))
            if teleport_pos is not None:
                ti, tj = teleport_pos
                # Cost of teleport move is 2 (as specified)
                new_cost = cost + 2
                new_moves = moves + 'T'

                state = (ti, tj)
                if state not in dist:
                    dist[state] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, ti, tj))
                else:
                    existing_cost, existing_moves = dist[state]
                    if new_cost < existing_cost:
                        dist[state] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, ti, tj))
                    elif new_cost == existing_cost and new_moves < existing_moves:
                        dist[state] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, ti, tj))

    # No path found
    return None
