def interpolate_all(data: dict[str, dict[str, str]]) -> None:
    # Resolve references recursively
    def resolve_value(section: str, key: str, visited: set[tuple[str, str]]) -> str:
        if (section, key) in visited:
            raise ValueError(f"cycle detected in interpolation for section '{section}', key '{key}'")

        if section not in data or key not in data[section]:
            raise ValueError(f"undefined reference ${section}:{key}$")

        value = data[section][key]

        # Find all ${...} patterns
        pattern = r'\$\{([^}:]+)\}'
        matches = list(re.finditer(pattern, value))

        if not matches:
            return value

        # Process from right to left to preserve positions
        result = value
        for match in reversed(matches):
            ref = match.group(1)
            # Check if it's ${section:key} or ${key}
            if ':' in ref:
                parts = ref.split(':', 1)
                if len(parts) != 2:
                    raise ValueError(f"invalid interpolation syntax: ${ref}$")
                ref_section, ref_key = parts
            else:
                ref_section = section
                ref_key = ref

            # Resolve the reference
            resolved = resolve_value(ref_section, ref_key, visited | {(section, key)})
            # Replace in result
            start, end = match.start(), match.end()
            result = result[:start] + resolved + result[end:]

        return result

    # Perform interpolation for all entries
    # Make a copy to avoid modifying during iteration
    for section in list(data.keys()):
        for key in list(data[section].keys()):
            data[section][key] = resolve_value(section, key, set())

    return data
