import re
from typing import Optional, List, Tuple, Set
from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

        # Validate: no leading zeros in numeric parts or numeric prerelease identifiers
        if major < 0 or minor < 0 or patch < 0:
            raise ValueError("Version numbers must be non-negative")
        if (major > 0 and str(major).startswith('0')) or \
           (minor > 0 and str(minor).startswith('0')) or \
           (patch > 0 and str(patch).startswith('0')):
            raise ValueError("No leading zeros in major, minor, or patch")

        # Validate prerelease identifiers: must be [0-9A-Za-z-]+ non-empty
        if prerelease:
            # Check for leading zeros in numeric identifiers
            identifiers = prerelease.split('.')
            for ident in identifiers:
                if not re.match(r'^[0-9A-Za-z-]+$', ident):
                    raise ValueError(f"Invalid prerelease identifier: {ident}")
                # Check numeric leading zeros
                if ident.isdigit() and len(ident) > 1 and ident.startswith('0'):
                    raise ValueError(f"Numeric prerelease identifier cannot have leading zeros: {ident}")

        # Validate build metadata: must be [0-9A-Za-z-]+ non-empty if present
        if build:
            if not re.match(r'^[0-9A-Za-z-]+$', build):
                raise ValueError(f"Invalid build metadata: {build}")

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f"-{self.prerelease}"
        if self.build:
            s += f"+{self.build}"
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major, self.minor, self.patch, self.prerelease) == \
               (other.major, other.minor, other.patch, other.prerelease)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __lt__(self, other):
        """Compare versions by SemVer precedence (build metadata ignored)"""
        if not isinstance(other, Version):
            return NotImplemented

        # Compare major, minor, patch
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

        # If one has prerelease and the other doesn't, the one with prerelease is less
        if self.prerelease is None and other.prerelease is not None:
            return False
        if self.prerelease is not None and other.prerelease is None:
            return True
        if self.prerelease is None and other.prerelease is None:
            return False

        # Both have prerelease, compare lexically
        return self._compare_prerelease(self.prerelease, other.prerelease) < 0

    @staticmethod
    def _compare_prerelease(pre1: str, pre2: str) -> int:
        """Compare two prerelease strings"""
        ids1 = pre1.split('.')
        ids2 = pre2.split('.')

        for i in range(min(len(ids1), len(ids2))):
            id1, id2 = ids1[i], ids2[i]

            # Check if both are numeric
            num1 = id1.isdigit()
            num2 = id2.isdigit()

            if num1 and num2:
                # Compare numerically
                n1, n2 = int(id1), int(id2)
                if n1 != n2:
                    return n1 - n2
            elif num1:
                # Numeric < alphanumeric
                return -1
            elif num2:
                # Alphanumeric > numeric
                return 1
            else:
                # Both alphanumeric: ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # Shorter list is smaller if all compared identifiers are equal
        return len(ids1) - len(ids2)


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 string"""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    v = v.strip()

    # Handle leading v or =
    if v.startswith('v') or v.startswith('='):
        v = v[1:].strip()

    # Pattern for SemVer 2.0.0
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, v)
    if not match:
        raise ValueError(f"Invalid version: {v}")

    major, minor, patch, prerelease, build = match.groups()

    return Version(int(major), int(minor), int(patch), prerelease, build)


class ComparatorSet:
    """A set of comparators that must all be satisfied"""
    def __init__(self):
        self.comparators = []

    def add_comparator(self, op: str, version: Version, is_xrange: bool = False):
        self.comparators.append((op, version, is_xrange))

    def satisfies(self, version: Version) -> bool:
        """Check if version satisfies this comparator set"""
        for op, comp_version, is_xrange in self.comparators:
            if not self._satisfies_comparator(version, op, comp_version, is_xrange):
                return False
        return True

    def _satisfies_comparator(self, version: Version, op: str, comp_version: Version, is_xrange: bool) -> bool:
        """Check if version satisfies a single comparator"""
        if op == '==':
            # Exact match (ignoring build metadata)
            return version.major == comp_version.major and \
                   version.minor == comp_version.minor and \
                   version.patch == comp_version.patch and \
                   version.prerelease == comp_version.prerelease
        elif op == '>=':
            return version >= comp_version
        elif op == '>':
            # > excludes exact version match
            return version > comp_version
        elif op == '<=':
            return version <= comp_version
        elif op == '<':
            # < excludes exact version match
            return version < comp_version
        elif op == '' or op is None:  # implicit ==
            # For exact versions
            return version.major == comp_version.major and \
                   version.minor == comp_version.minor and \
                   version.patch == comp_version.patch and \
                   version.prerelease == comp_version.prerelease
        return True


class Range:
    """A range with one or more comparator sets joined by ||"""
    def __init__(self):
        self.comparator_sets: List[ComparatorSet] = []

    def add_comparator_set(self, cs: ComparatorSet):
        self.comparator_sets.append(cs)

    def satisfies(self, version: Version) -> bool:
        """Check if version satisfies this range"""
        # Check if any comparator set is satisfied
        for cs in self.comparator_sets:
            if cs.satisfies(version):
                return True
        return False

    def satisfies_prerelease(self, version: Version) -> bool:
        """Check if prerelease version satisfies this range according to npm rules"""
        # For prerelease versions, all comparators in a set must have the same MAJOR.MINOR.PATCH as the version
        # and the same prerelease (if any)
        if version.prerelease is None:
            return self.satisfies(version)

        # Check each comparator set
        for cs in self.comparator_sets:
            # For prerelease versions, all comparators must match the version
            # Specifically: if any comparator has a prerelease part, the version must have the same MAJOR.MINOR.PATCH
            # and the comparator's prerelease must be a prefix of the version's prerelease

            # Check if all comparators in this set are satisfied
            all_satisfied = True
            for op, comp_version, is_xrange in cs.comparators:
                if not self._satisfies_comparator_with_prerelease(version, op, comp_version, is_xrange):
                    all_satisfied = False
                    break

            if all_satisfied:
                return True

        return False

    def _satisfies_comparator_with_prerelease(self, version: Version, op: str, comp_version: Version, is_xrange: bool) -> bool:
        """Check satisfaction with prerelease rules"""
        if op == '>=':
            # >= requires version >= comp_version
            # But also: if version is prerelease, comp_version must be same major.minor.patch with compatible prerelease
            if comp_version.prerelease and version.major == comp_version.major and \
               version.minor == comp_version.minor and \
               version.patch == comp_version.patch:
                # Same version but different prerelease: check prerelease comparison
                # For prerelease comparison: version.prerelease must be >= comp_version.prerelease
                # Actually: version.prerelease > comp_version.prerelease (more specific prerelease is greater)
                # But SemVer: 1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
                # So if version is 1.0.0-alpha.1 and comp is 1.0.0-alpha, then version > comp
                # This means we need version >= comp
                return version >= comp_version
            else:
                # Otherwise just standard comparison
                return version >= comp_version
        elif op == '>':
            # > requires version > comp_version
            if comp_version.prerelease and version.major == comp_version.major and \
               version.minor == comp_version.minor and \
               version.patch == comp_version.patch:
                return version > comp_version
            else:
                return version > comp_version
        elif op == '<=':
            return version <= comp_version
        elif op == '<':
            return version < comp_version
        elif op == '==':
            return version.major == comp_version.major and \
                   version.minor == comp_version.minor and \
                   version.patch == comp_version.patch and \
                   version.prerelease == comp_version.prerelease
        elif op == '' or op is None:
            return version.major == comp_version.major and \
                   version.minor == comp_version.minor and \
                   version.patch == comp_version.patch and \
                   version.prerelease == comp_version.prerelease
        return True


def parse_partial_version(v_str: str) -> Version:
    """Parse a partial version string (e.g. '1', '1.2', '1.2.3')"""
    if not v_str:
        raise ValueError("Empty version string")

    parts = v_str.split('.')

    # Check for invalid patterns like '1.02' (leading zeros in minor or patch)
    for i, part in enumerate(parts):
        if i >= 3:  # Only major, minor, patch are allowed
            break
        if part == '*':
            # Handle wildcard case
            continue
        if not part:
            continue
        if not re.match(r'^0$|^[1-9][0-9]*$', part):
            raise ValueError(f"Invalid version part: {part}")

    major = 0
    minor = 0
    patch = 0

    try:
        if parts[0] != '*' and parts[0]:
            major = int(parts[0])
    except (ValueError, IndexError):
        raise ValueError(f"Invalid major version: {v_str}")

    try:
        if len(parts) > 1 and parts[1] != '*' and parts[1]:
            minor = int(parts[1])
    except (ValueError, IndexError):
        raise ValueError(f"Invalid minor version: {v_str}")

    try:
        if len(parts) > 2 and parts[2] != '*' and parts[2]:
            patch = int(parts[2])
    except (ValueError, IndexError):
        raise ValueError(f"Invalid patch version: {v_str}")

    return Version(major, minor, patch)


def parse_comparator(comp_str: str, prerelease_allowed: bool = False) -> Tuple[str, Version, bool]:
    """Parse a comparator string like '>=1.2.3', '1.2.x', etc. Returns (op, version, is_xrange)"""
    comp_str = comp_str.strip()

    # Extract operator
    op = None
    if comp_str.startswith('>='):
        op = '>='
        comp_str = comp_str[2:]
    elif comp_str.startswith('<='):
        op = '<='
        comp_str = comp_str[2:]
    elif comp_str.startswith('>'):
        op = '>'
        comp_str = comp_str[1:]
    elif comp_str.startswith('<'):
        op = '<'
        comp_str = comp_str[1:]
    elif comp_str.startswith('='):
        op = '=='
        comp_str = comp_str[1:]
    # No operator means implicit '=' or exact match

    comp_str = comp_str.strip()

    # Handle wildcard versions
    if comp_str == '*' or comp_str == '':
        # Empty or wildcard matches all
        return ('', Version(0, 0, 0), True)

    # Handle X-ranges
    is_xrange = False

    # Count parts
    parts = comp_str.split('.')

    # Check for X in parts
    has_x = any(p == 'x' or p == 'X' for p in parts)
    if has_x:
        is_xrange = True
        # Replace X with 0
        parts = [p.lower() if p == 'x' else p for p in parts]

    # Parse version
    try:
        if len(parts) == 1:
            major = parts[0]
            if major.lower() == 'x':
                return ('', Version(0, 0, 0), True)
            return ('', Version(int(major), 0, 0), False)
        elif len(parts) == 2:
            major = parts[0]
            minor = parts[1]
            if minor.lower() == 'x':
                is_xrange = True
                minor = 0
            return ('', Version(int(major), int(minor), 0), is_xrange)
        elif len(parts) >= 3:
            major = parts[0]
            minor = parts[1]
            patch = parts[2]
            if patch.lower() == 'x':
                is_xrange = True
                patch = 0
            return ('', Version(int(major), int(minor), int(patch)), is_xrange)
        else:
            raise ValueError(f"Invalid version: {comp_str}")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid version: {comp_str}") from e


def parse_range(range_str: str) -> Range:
    """Parse a range string"""
    range_obj = Range()

    # Split by ||
    sets = range_str.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            # Empty set means matches all
            continue

        # Split by whitespace
        parts = set_str.split()
        if not parts:
            # Empty set
            continue

        cs = ComparatorSet()

        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Check if it's a hyphen range
            if part == '-':
                # This should be handled differently, but we'll process as part of range
                # Actually, hyphen ranges are 'v1 - v2', so we need to handle differently
                # Let's defer this to a more sophisticated parser
                pass

            # Check for operators
            if part in ('<', '>', '<=', '>=', '==', '='):
                # Incomplete comparator, invalid
                raise ValueError(f"Invalid comparator: {part}")

            # Handle hyphen ranges separately
            # For now, assume simple comparators
            if re.match(r'^[\dXx\*]', part):
                op = None
                version_str = part

                # Check if starts with operator
                if part.startswith('>='):
                    op = '>='
                    version_str = part[2:]
                elif part.startswith('<='):
                    op = '<='
                    version_str = part[2:]
                elif part.startswith('>'):
                    op = '>'
                    version_str = part[1:]
                elif part.startswith('<'):
                    op = '<'
                    version_str = part[1:]
                elif part.startswith('=='):
                    op = '=='
                    version_str = part[2:]
                elif part.startswith('='):
                    op = '=='
                    version_str = part[1:]

                # Parse the version
                if version_str == '*' or version_str.lower() == 'x':
                    version = Version(0, 0, 0)
                    cs.add_comparator(op or '', version, True)
                    continue

                # Handle tilde and caret
                if part.startswith('~') or part.startswith('^'):
                    if part.startswith('~'):
                        # Tilde range
                        ver_str = part[1:].strip()
                        # Parse as partial version
                        base_version = parse_partial_version(ver_str)
                        op_base = '>='
                        op_upper = '<'

                        # Determine upper bound
                        if base_version.patch != 0:
                            # ~1.2.3 -> >=1.2.3 <1.3.0
                            upper_version = Version(base_version.major, base_version.minor, base_version.patch + 1)
                        elif base_version.minor != 0:
                            # ~1.2 -> >=1.2.0 <1.3.0
                            upper_version = Version(base_version.major, base_version.minor + 1, 0)
                        else:
                            # ~1 -> >=1.0.0 <2.0.0
                            upper_version = Version(base_version.major + 1, 0, 0)

                        cs.add_comparator(op_base, base_version, False)
                        cs.add_comparator(op_upper, upper_version, False)
                        continue
                    elif part.startswith('^'):
                        # Caret range
                        ver_str = part[1:].strip()
                        base_version = parse_partial_version(ver_str)

                        # Determine upper bound
                        if base_version.major == 0:
                            if base_version.minor == 0:
                                # ^0.0.x -> >=0.0.0 <0.1.0
                                upper_version = Version(0, 1, 0)
                            else:
                                # ^0.x -> >=0.0.0 <1.0.0
                                upper_version = Version(0, base_version.minor + 1, 0) if base_version.minor != 0 else Version(0, 1, 0)
                        else:
                            # ^1.x -> >=1.0.0 <2.0.0
                            upper_version = Version(base_version.major + 1, 0, 0)

                        # For exact match (like ^1.2.3), we use the base version as lower bound
                        cs.add_comparator('>=', base_version, False)
                        cs.add_comparator('<', upper_version, False)
                        continue

                # Handle partial versions for X-ranges with operators
                if part == '0.x' or part == '0.X':
                    cs.add_comparator('>=', Version(0, 0, 0), True)
                    cs.add_comparator('<', Version(0, 1, 0), True)
                    continue

                # For normal parsing
                op_version = parse_version_string(part)

                # Add the comparator
                op_actual = op or ''
                cs.add_comparator(op_actual, op_version, False)

        # Special handling for hyphen ranges: v1 - v2
        # We'll process this after collecting all parts

        # Check if there's a hyphen in the set
        if ' - ' in set_str:
            # Parse the hyphen range
            hyphen_parts = set_str.split(' - ')
            if len(hyphen_parts) == 2:
                lower_str = hyphen_parts[0].strip()
                upper_str = hyphen_parts[1].strip()

                # Remove any operators from lower_str
                # Parse as versions
                lower_version = parse_version_string(lower_str)
                upper_version = parse_version_string(upper_str)

                # Reset comparator set to handle hyphen
                cs = ComparatorSet()
                cs.add_comparator('>=', lower_version, False)

                # Upper bound: if upper is partial and not exact patch, it's exclusive next
                upper_is_partial = (upper_version.minor != 0 or upper_version.patch != 0) and \
                                  (not re.match(r'^\d+\.\d+\.\d+$', upper_str))

                # Check if upper_str is a partial version (e.g., '1.2' instead of '1.2.3')
                if '.' in upper_str and not upper_str.count('.') >= 2:
                    # It's partial, so it's exclusive next
                    if upper_version.patch == 0:
                        if upper_version.minor == 0:
                            # Upper is like '1' -> <2.0.0
                            upper_exclusive = Version(upper_version.major + 1, 0, 0)
                        else:
                            # Upper is like '1.2' -> <1.3.0
                            upper_exclusive = Version(upper_version.major, upper_version.minor + 1, 0)
                    else:
                        # Upper is like '1.2.3' -> <=1.2.3
                        upper_exclusive = Version(upper_version.major, upper_version.minor, upper_version.patch + 1)
                        cs.add_comparator('<', upper_exclusive, False)
                else:
                    # Exact version: <=
                    cs.add_comparator('<=', upper_version, False)

                # Actually, the correct behavior:
                # '1.2.3 - 2.3' means >=1.2.3 <2.4.0 (upper is filled with zeros then next patch)
                # Let's simplify: always use lower bound >= and upper bound as appropriate
                cs = ComparatorSet()
                cs.add_comparator('>=', lower_version, False)

                # Upper bound logic:
                # If upper_str is partial, fill zeros and use < next
                parts_upper = upper_str.split('.')
                if len(parts_upper) < 3:
                    # Fill with zeros
                    while len(parts_upper) < 3:
                        parts_upper.append('0')
                    # Convert to integers
                    upper_version = Version(int(parts_upper[0]), int(parts_upper[1]), int(parts_upper[2]))
                    # Use < next
                    if upper_version.patch == 0:
                        if upper_version.minor == 0:
                            upper_exclusive = Version(upper_version.major + 1, 0, 0)
                        else:
                            upper_exclusive = Version(upper_version.major, upper_version.minor + 1, 0)
                    else:
                        upper_exclusive = Version(upper_version.major, upper_version.minor, upper_version.patch + 1)
                else:
                    # Exact version: use <=
                    upper_exclusive = Version(upper_version.major, upper_version.minor, upper_version.patch + 1)

                cs.add_comparator('<', upper_exclusive, False)
            else:
                raise ValueError(f"Invalid hyphen range: {set_str}")

        range_obj.add_comparator_set(cs)

    # Handle the case of empty range or just '*'
    if not range_obj.comparator_sets:
        # Empty range matches nothing, but we want to handle '*' and empty sets specially
        pass
    else:
        # Check if any set is just '*' or empty
        for cs in range_obj.comparator_sets:
            if not cs.comparators:
                # Empty comparator set matches everything
                range_obj.comparator_sets = []
                break

    return range_obj


def parse_version_string(v_str: str) -> Version:
    """Parse a version string that may be partial"""
    v_str = v_str.strip()

    # Handle wildcard
    if v_str == '*' or v_str.lower() == 'x':
        return Version(0, 0, 0)

    # Split into parts
    parts = v_str.split('.')

    # Handle partial versions
    if len(parts) == 1:
        if parts[0].isdigit():
            return Version(int(parts[0]), 0, 0)
        else:
            raise ValueError(f"Invalid version: {v_str}")
    elif len(parts) == 2:
        if parts[0].isdigit() and parts[1].isdigit():
            return Version(int(parts[0]), int(parts[1]), 0)
        elif parts[0].isdigit() and (parts[1] == 'x' or parts[1].lower() == 'x'):
            return Version(int(parts[0]), 0, 0)
        else:
            raise ValueError(f"Invalid version: {v_str}")
    elif len(parts) == 3:
        if parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit():
            return Version(int(parts[0]), int(parts[1]), int(parts[2]))
        elif parts[0].isdigit() and parts[1].isdigit() and (parts[2] == 'x' or parts[2].lower() == 'x'):
            return Version(int(parts[0]), int(parts[1]), 0)
        else:
            raise ValueError(f"Invalid version: {v_str}")
    else:
        raise ValueError(f"Invalid version: {v_str}")


def satisfies(version: str, rng: str) -> bool:
    """Check if version satisfies range"""
    try:
        ver = parse(version)
    except ValueError:
        raise ValueError(f"Invalid version: {version}")

    try:
        range_obj = parse_range(rng)
    except ValueError:
        raise ValueError(f"Invalid range: {rng}")

    # Special case: prerelease versions
    if ver.prerelease is not None:
        # Prerelease versions only satisfy if the range includes a prerelease with same major.minor.patch
        # We need to check if any comparator set has a version with same major.minor.patch and a prerelease
        return range_obj.satisfies_prerelease(ver)
    else:
        return range_obj.satisfies(ver)


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version that satisfies the range, or None"""
    if not versions:
        return None

    try:
        range_obj = parse_range(rng)
    except ValueError:
        raise ValueError(f"Invalid range: {rng}")

    satisfying_versions = []
    for v_str in versions:
        try:
            if satisfies(v_str, rng):
                satisfying_versions.append(parse(v_str))
        except ValueError:
            # Skip invalid versions
            continue

    if not satisfying_versions:
        return None

    # Find max version using our Version comparison
    max_ver = max(satisfying_versions)

    # Return the original string
    for v_str in versions:
        try:
            if parse(v_str) == max_ver:
                return v_str
        except ValueError:
            continue

    return None


def parse_range(range_str: str) -> Range:
    """Parse a range string"""
    range_obj = Range()

    # Split by ||
    sets = range_str.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            # Empty set means matches all
            cs = ComparatorSet()
            # Add a wildcard comparator
            cs.add_comparator('', Version(0, 0, 0), True)
            range_obj.add_comparator_set(cs)
            continue

        # Split by whitespace
        parts = set_str.split()
        if not parts:
            # Empty set
            cs = ComparatorSet()
            cs.add_comparator('', Version(0, 0, 0), True)
            range_obj.add_comparator_set(cs)
            continue

        cs = ComparatorSet()

        # Check for hyphen range first
        if ' - ' in set_str:
            hyphen_parts = set_str.split(' - ')
            if len(hyphen_parts) == 2:
                lower_str = hyphen_parts[0].strip()
                upper_str = hyphen_parts[1].strip()

                # Parse lower version
                lower_ver = parse_version_string(lower_str)
                # For lower bound, if it's partial, pad with zeros
                if lower_ver.minor == 0 and lower_ver.patch == 0:
                    lower_ver = Version(lower_ver.major, 0, 0)
                elif lower_ver.patch == 0:
                    lower_ver = Version(lower_ver.major, lower_ver.minor, 0)

                # Parse upper version
                upper_ver = parse_version_string(upper_str)
                # For upper bound, if it's partial, it's exclusive next
                if upper_ver.minor == 0 and upper_ver.patch == 0:
                    # e.g., '1' -> <2.0.0
                    upper_excl = Version(upper_ver.major + 1, 0, 0)
                elif upper_ver.patch == 0:
                    # e.g., '1.2' -> <1.3.0
                    upper_excl = Version(upper_ver.major, upper_ver.minor + 1, 0)
                else:
                    # e.g., '1.2.3' -> <=1.2.3 or <1.2.4
                    upper_excl = Version(upper_ver.major, upper_ver.minor, upper_ver.patch + 1)

                cs.add_comparator('>=', lower_ver, False)
                cs.add_comparator('<', upper_excl, False)
                range_obj.add_comparator_set(cs)
                continue
            else:
                raise ValueError(f"Invalid hyphen range: {set_str}")

        # Process each part as a comparator
        for i, part in enumerate(parts):
            part = part.strip()
            if not part:
                continue

            # Handle tilde
            if part.startswith('~'):
                ver_str = part[1:].strip()
                base_ver = parse_version_string(ver_str)
                # Determine upper bound
                if base_ver.patch != 0:
                    # ~1.2.3 -> >=1.2.3 <1.3.0
                    upper_ver = Version(base_ver.major, base_ver.minor, base_ver.patch + 1)
                elif base_ver.minor != 0:
                    # ~1.2 -> >=1.2.0 <1.3.0
                    upper_ver = Version(base_ver.major, base_ver.minor + 1, 0)
                else:
                    # ~1 -> >=1.0.0 <2.0.0
                    upper_ver = Version(base_ver.major + 1, 0, 0)

                cs.add_comparator('>=', base_ver, False)
                cs.add_comparator('<', upper_ver, False)
                continue

            # Handle caret
            if part.startswith('^'):
                ver_str = part[1:].strip()
                base_ver = parse_version_string(ver_str)

                # Determine upper bound based on npm rules
                if base_ver.major == 0:
                    if base_ver.minor == 0:
                        # ^0.0.x -> >=0.0.0 <0.1.0
                        upper_ver = Version(0, 1, 0)
                    else:
                        # ^0.x -> >=0.0.0 <1.0.0
                        upper_ver = Version(0, base_ver.minor + 1, 0)
                else:
                    # ^1.x -> >=1.0.0 <2.0.0
                    upper_ver = Version(base_ver.major + 1, 0, 0)

                cs.add_comparator('>=', base_ver, False)
                cs.add_comparator('<', upper_ver, False)
                continue

            # Check for operators
            op = None
            ver_str = part

            if part.startswith('>='):
                op = '>='
                ver_str = part[2:]
            elif part.startswith('<='):
                op = '<='
                ver_str = part[2:]
            elif part.startswith('>'):
                op = '>'
                ver_str = part[1:]
            elif part.startswith('<'):
                op = '<'
                ver_str = part[1:]
            elif part.startswith('=='):
                op = '=='
                ver_str = part[2:]
            elif part.startswith('='):
                op = '=='
                ver_str = part[1:]

            # Parse version string
            if ver_str == '*' or ver_str.lower() == 'x':
                cs.add_comparator(op or '', Version(0, 0, 0), True)
                continue

            # Handle X-ranges (e.g., '1.2.x')
            if 'x' in ver_str or 'X' in ver_str:
                parts_x = ver_str.split('.')
                # Replace x/X with 0
                major = 0
                minor = 0
                patch = 0
                try:
                    if parts_x[0].lower() != 'x':
                        major = int(parts_x[0])
                except ValueError:
                    raise ValueError(f"Invalid major version: {ver_str}")

                if len(parts_x) > 1 and parts_x[1].lower() != 'x':
                    try:
                        minor = int(parts_x[1])
                    except ValueError:
                        raise ValueError(f"Invalid minor version: {ver_str}")

                if len(parts_x) > 2 and parts_x[2].lower() != 'x':
                    try:
                        patch = int(parts_x[2])
                    except ValueError:
                        raise ValueError(f"Invalid patch version: {ver_str}")

                base_ver = Version(major, minor, patch)
                is_xrange = True

                # For X-ranges, determine upper bound
                if base_ver.major == 0:
                    if base_ver.minor == 0:
                        # 0.0.x -> <0.1.0
                        upper_ver = Version(0, 1, 0)
                    else:
                        # 0.x -> <0.(minor+1).0
                        upper_ver = Version(0, base_ver.minor + 1, 0)
                else:
                    # X range -> <(major+1).0.0
                    upper_ver = Version(base_ver.major + 1, 0, 0)

                cs.add_comparator(op or '>=', base_ver, False)
                if op not in ('>', '>='):
                    cs.add_comparator('<', upper_ver, False)
                continue

            # Normal version parsing
            try:
                ver = parse_version_string(ver_str)
            except ValueError as e:
                raise ValueError(f"Invalid version in comparator: {ver_str}") from e

            # Add comparator
            cs.add_comparator(op or '', ver, False)

        range_obj.add_comparator_set(cs)

    return range_obj


