from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

        # Validate: no leading zeros in numeric parts or numeric prerelease identifiers
        if major < 0 or minor < 0 or patch < 0:
            raise ValueError("Version numbers must be non-negative")

        # Check major, minor, patch for leading zeros (except 0 itself)
        for val, name in [(major, 'major'), (minor, 'minor'), (patch, 'patch')]:
            if val != 0 and str(val).startswith('0'):
                raise ValueError(f"{name} version cannot have leading zeros")

        # Validate prerelease identifiers: must be [0-9A-Za-z-]+ non-empty
        if prerelease:
            identifiers = prerelease.split('.')
            for ident in identifiers:
                if not re.match(r'^[0-9A-Za-z-]+$', ident):
                    raise ValueError(f"Invalid prerelease identifier: {ident}")
                # Check numeric leading zeros
                if ident.isdigit() and len(ident) > 1:
                    raise ValueError(f"Numeric prerelease identifier cannot have leading zeros: {ident}")

        # Validate build metadata: must be [0-9A-Za-z-]+ non-empty if present
        if build:
            identifiers = build.split('.')
            for ident in identifiers:
                if not re.match(r'^[0-9A-Za-z-]+$', ident):
                    raise ValueError(f"Invalid build metadata identifier: {ident}")

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f"-{self.prerelease}"
        if self.build:
            s += f"+{self.build}"
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major, self.minor, self.patch, self.prerelease) == \
               (other.major, other.minor, other.patch, other.prerelease)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __lt__(self, other):
        """Compare versions by SemVer precedence (build metadata ignored)"""
        if not isinstance(other, Version):
            return NotImplemented

        # Compare major, minor, patch
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

        # If one has prerelease and the other doesn't, the one with prerelease is less
        if self.prerelease is None and other.prerelease is not None:
            return False
        if self.prerelease is not None and other.prerelease is None:
            return True
        if self.prerelease is None and other.prerelease is None:
            return False

        # Both have prerelease, compare lexically
        return self._compare_prerelease(self.prerelease, other.prerelease) < 0

    @staticmethod
    def _compare_prerelease(pre1: str, pre2: str) -> int:
        """Compare two prerelease strings"""
        ids1 = pre1.split('.')
        ids2 = pre2.split('.')

        for i in range(min(len(ids1), len(ids2))):
            id1, id2 = ids1[i], ids2[i]

            # Check if both are numeric
            num1 = id1.isdigit()
            num2 = id2.isdigit()

            if num1 and num2:
                # Compare numerically
                n1, n2 = int(id1), int(id2)
                if n1 != n2:
                    return n1 - n2
            elif num1:
                # Numeric < alphanumeric
                return -1
            elif num2:
                # Alphanumeric > numeric
                return 1
            else:
                # Both alphanumeric: ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # Shorter list is smaller if all compared identifiers are equal
        return len(ids1) - len(ids2)


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 string"""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    v = v.strip()

    # Handle leading v or =
    if v.startswith('v') or v.startswith('='):
        v = v[1:].strip()

    # Pattern for SemVer 2.0.0
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, v)
    if not match:
        raise ValueError(f"Invalid version: {v}")

    major, minor, patch, prerelease, build = match.groups()

    return Version(int(major), int(minor), int(patch), prerelease, build)


class ComparatorSet:
    """A set of comparators that must all be satisfied"""
    def __init__(self):
        self.comparators = []

    def add_comparator(self, op: str, version: Version, is_xrange: bool = False):
        self.comparators.append((op, version, is_xrange))

    def satisfies(self, version: Version) -> bool:
        """Check if version satisfies this comparator set"""
        for op, comp_version, is_xrange in self.comparators:
            if not self._satisfies_comparator(version, op, comp_version, is_xrange):
                return False
        return True

    def _satisfies_comparator(self, version: Version, op: str, comp_version: Version, is_xrange: bool) -> bool:
        """Check if version satisfies a single comparator"""
        if op == '>=':
            return version >= comp_version
        elif op == '>':
            # > excludes exact version match
            return version > comp_version
        elif op == '<=':
            return version <= comp_version
        elif op == '<':
            # < excludes exact version match
            return version < comp_version
        elif op == '' or op is None:  # implicit exact match
            # For exact versions
            return version.major == comp_version.major and \
                   version.minor == comp_version.minor and \
                   version.patch == comp_version.patch and \
                   version.prerelease == comp_version.prerelease
        return True


class Range:
    """A range with one or more comparator sets joined by ||"""
    def __init__(self):
        self.comparator_sets: List[ComparatorSet] = []

    def add_comparator_set(self, cs: ComparatorSet):
        self.comparator_sets.append(cs)

    def satisfies(self, version: Version) -> bool:
        """Check if version satisfies this range"""
        # Check if any comparator set is satisfied
        for cs in self.comparator_sets:
            if cs.satisfies(version):
                return True
        return False


