    if not v_str or v_str == '*' or v_str.lower() == 'x':
        return Version(0, 0, 0)

    parts = v_str.split('.')

    # Handle wildcard parts
    major = 0
    minor = 0
    patch = 0

    try:
        if parts[0].lower() != 'x':
            major = int(parts[0])
    except (ValueError, IndexError):
        raise ValueError(f"Invalid major version: {v_str}")

    if len(parts) > 1 and parts[1].lower() != 'x':
        try:
