    # Split into parts
    parts = v_str.split('.')

    # Handle partial versions
    if len(parts) == 1:
        if parts[0].lower() == 'x':
            return Version(0, 0, 0)
        if parts[0].isdigit():
            return Version(int(parts[0]), 0, 0)
        else:
            raise ValueError(f"Invalid version: {v_str}")
    elif len(parts) == 2:
        major = 0
        minor = 0
        if parts[0].lower() != 'x':
            if not parts[0].isdigit():
                raise ValueError(f"Invalid major version: {v_str}")
            major = int(parts[0])
        else:
            major = 0

        if parts[1].lower() != 'x':
            if not parts[1].isdigit():
                raise ValueError(f"Invalid minor version: {v_str}")
            minor = int(parts[1])
        else:
            minor = 0

        return Version(major, minor, 0)
    elif len(parts) == 3:
        major = 0
        minor = 0
        patch = 0
        if parts[0].lower() != 'x':
            if not parts[0].isdigit():
                raise ValueError(f"Invalid major version: {v_str}")
            major = int(parts[0])
        else:
            major = 0

        if parts[1].lower() != 'x':
            if not parts[1].isdigit():
                raise ValueError(f"Invalid minor version: {v_str}")
            minor = int(parts[1])
        else:
            minor = 0

        if parts[2].lower() != 'x':
            if not parts[2].isdigit():
                raise ValueError(f"Invalid patch version: {v_str}")
            patch = int(parts[2])
        else:
            patch = 0

        return Version(major, minor, patch)
    else:
        raise ValueError(f"Invalid version: {v_str}")


def parse_range(range_str: str) -> Range:
    """Parse a range string"""
    range_obj = Range()

    # Split by ||
    sets = range_str.split('||')

    for set_str in sets:
        set_str = set_str.strip()
        if not set_str:
            # Empty set means matches all
            cs = ComparatorSet()
            cs.add_comparator('', Version(0, 0, 0), True)
            range_obj.add_comparator_set(cs)
            continue

        # Check for hyphen range first
        if ' - ' in set_str:
            hyphen_parts = set_str.split(' - ')
            if len(hyphen_parts) == 2:
                lower_str = hyphen_parts[0].strip()
                upper_str = hyphen_parts[1].strip()

                # Parse lower version
                lower_ver = parse_version_string(lower_str)

                # Parse upper version - it's exclusive next if partial
                # If upper_str is a partial version, it's exclusive next
                # If upper_str has wildcard or X, it's also exclusive next

                # Check if upper_str is a partial version (doesn't have 3 parts or has wildcards)
                upper_is_partial = False
                if upper_str == '*' or upper_str.lower() == 'x':
                    upper_is_partial = True
                elif '.' not in upper_str:
                    upper_is_partial = True
                elif upper_str.count('.') == 1 and (upper_str.endswith('x') or upper_str.endswith('X')):
                    upper_is_partial = True

                if upper_is_partial:
                    # Parse upper as partial and get next version
                    upper_ver = parse_version_string(upper_str)
                    if upper_ver.patch != 0:
                        upper_excl = Version(upper_ver.major, upper_ver.minor, upper_ver.patch + 1)
                    elif upper_ver.minor != 0:
                        upper_excl = Version(upper_ver.major, upper_ver.minor + 1, 0)
                    else:
                        upper_excl = Version(upper_ver.major + 1, 0, 0)
                else:
