                        upper_ver = Version(0, base_ver.minor + 1, 0)
                else:
                    # ^1.x -> >=1.0.0 <2.0.0
                    upper_ver = Version(base_ver.major + 1, 0, 0)

                cs.add_comparator('>=', base_ver, False)
                cs.add_comparator('<', upper_ver, False)
                continue

            # Check for operators
            op = None
            ver_str = part

            if part.startswith('>='):
                op = '>='
                ver_str = part[2:]
            elif part.startswith('<='):
                op = '<='
                ver_str = part[2:]
            elif part.startswith('>'):
                op = '>'
                ver_str = part[1:]
            elif part.startswith('<'):
                op = '<'
                ver_str = part[1:]
            elif part.startswith('=='):
                op = '=='
                ver_str = part[2:]
            elif part.startswith('='):
