        # For prerelease versions, they must satisfy all comparators in a set
        # AND at least one comparator must have the same major.minor.patch
        # and a prerelease part that is compatible

        # Check each comparator set
        for cs in range_obj.comparator_sets:
            # Check if all comparators in this set are satisfied
            all_satisfied = True
            has_matching_prerelease = False

            for op, comp_ver, is_xrange in cs.comparators:
                if op == '>=':
                    if ver < comp_ver:
                        all_satisfied = False
                        break
                    # Check if this comparator has same major.minor.patch and prerelease
                    if ver.major == comp_ver.major and ver.minor == comp_ver.minor and \
                       ver.patch == comp_ver.patch and comp_ver.prerelease:
                        has_matching_prerelease = True
                elif op == '>':
                    if ver <= comp_ver:
                        all_satisfied = False
                        break
                    if ver.major == comp_ver.major and ver.minor == comp_ver.minor and \
                       ver.patch == comp_ver.patch and comp_ver.prerelease:
                        has_matching_prerelease = True
                elif op == '<=':
                    if ver > comp_ver:
                        all_satisfied = False
                        break
                    if ver.major == comp_ver.major and ver.minor == comp_ver.minor and \
                       ver.patch == comp_ver.patch and comp_ver.prerelease:
                        has_matching_prerelease = True
                elif op == '<':
                    if ver >= comp_ver:
                        all_satisfied = False
                        break
                    if ver.major == comp_ver.major and ver.minor == comp_ver.minor and \
                       ver.patch == comp_ver.patch and comp_ver.prerelease:
                        has_matching_prerelease = True
                elif op == '' or op is None:
