                    if ver.major != comp_ver.major or ver.minor != comp_ver.minor or \
                       ver.patch != comp_ver.patch or ver.prerelease != comp_ver.prerelease:
                        all_satisfied = False
                        break
                    has_matching_prerelease = True

            if all_satisfied and has_matching_prerelease:
