def split_command(line: str, env: dict[str, str]) -> List[str]:
    """
    Parse a command line string into words, handling quoting, escaping, and parameter expansion.
    """
    result = []
    i = 0
    n = len(line)

    # Stack to track if we're in a double-quoted context (for expansion)
    # We'll process character by character and build words

    # Helper to get current position and advance
    def peek(offset=0):
        pos = i + offset
        return line[pos] if pos < n else None

    def advance():
        nonlocal i
        i += 1

    def parse_dollar_expansion():
        """Parse a $ expansion starting at current position (after the $)"""
        nonlocal i
        start = i  # position of $ is i-1

        # Check for ${...}
        if i < n and line[i] == '{':
            i += 1  # consume '{'
            var_start = i
            # Find matching '}'
            brace_depth = 1
            while i < n and brace_depth > 0:
                if line[i] == '{':
                    brace_depth += 1
                elif line[i] == '}':
                    brace_depth -= 1
                if brace_depth > 0:
                    i += 1

            if brace_depth != 0:
                raise ValueError("Unterminated ${")

            # Extract variable name part
            var_part = line[var_start:i]
            i += 1  # consume '}'

            # Check for :-default or -default
            default = None
            if var_part and var_part[0] == '-':
                # Error: missing variable name
                raise ValueError("Invalid variable syntax: ${-" + var_part + "}")

            # Split variable name and default
            colon_minus = var_part.find(":-")
            minus = var_part.find("-", 1) if len(var_part) > 1 else -1

            # Handle cases: NAME:-default, NAME-default
            if colon_minus != -1 and (minus == -1 or colon_minus < minus):
                # We have :- format
                var_name = var_part[:colon_minus]
                default_part = var_part[colon_minus + 2:]
                default = parse_default(default_part, env)
            elif minus != -1:
                # We have - format
                var_name = var_part[:minus]
                default_part = var_part[minus + 1:]
                default = parse_default(default_part, env)
            else:
                var_name = var_part

            # Validate variable name
            if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', var_name):
                raise ValueError(f"Invalid variable name: {var_name}")

            # Get value
            value = env.get(var_name, "")

            # Apply default logic
            if default is not None:
                if var_name == "":
                    raise ValueError("Empty variable name in expansion")
                # If unset (not in env) or empty string, use default
                if var_name not in env or env[var_name] == "":
                    value = default

            return value

        # Simple $NAME case
        var_start = i
        while i < n and (line[i].isalnum() or line[i] == '_'):
            i += 1

        if i == var_start:
            # No variable name follows, just a literal $
            return "$"

        var_name = line[var_start:i]
        if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', var_name):
            # Not a valid variable name, return $ followed by literal
            i = var_start  # Reset
            return "$" + line[var_start:i+1] if i < n else "$"

        value = env.get(var_name, "")
        return value

    def parse_default(default_part: str, env: dict) -> str:
        """Parse default value, handling nested $ expansions"""
        result = []
        j = 0
        m = len(default_part)

        while j < m:
