class LoadError(ValueError):
    def __init__(self, path, message):
        self.path = path
        super().__init__(f"{path}: {message}")


def _get_literal_values(annotation):
    """Extract literal values from a Literal annotation."""
    origin = get_origin(annotation)
    if origin is Literal:
        return get_args(annotation)
    return None


def _is_union_type(annotation):
    """Check if annotation is a union type (including Optional)."""
    origin = get_origin(annotation)
    return origin is Union


def _get_union_args(annotation):
    """Get the args of a union type."""
    return get_args(annotation)


def _is_optional(annotation):
    """Check if annotation is Optional (i.e., Union[T, None] or None | T)."""
    if _is_union_type(annotation):
        args = get_args(annotation)
        return type(None) in args
    return False


def _is_list_type(annotation):
    """Check if annotation is list[T]."""
    origin = get_origin(annotation)
    return origin is list


def _is_dict_type(annotation):
    """Check if annotation is dict[K, V]."""
    origin = get_origin(annotation)
    return origin is dict


def _is_tuple_type(annotation):
    """Check if annotation is tuple[...] (fixed or variable length)."""
    origin = get_origin(annotation)
    return origin is tuple


def _is_literal_type(annotation):
    """Check if annotation is Literal[...]."""
    return get_origin(annotation) is Literal


def _is_dataclass_type(annotation):
    """Check if annotation is a dataclass type."""
    return is_dataclass(annotation)


def _get_type_args(annotation):
    """Get type arguments (e.g., T for List[T])."""
    return get_args(annotation)


def _load_literal(data, expected_values):
    """Load a value that must be one of the expected literal values."""
    # Check if data matches any literal value and has the correct type
    for value in expected_values:
        if type(data) is type(value) and data == value:
            return data
    # If we get here, none of the literal values matched
    return None  # Will be handled by caller


