        ext = tolower(ext)
    }

    # Increment count
    count[ext]++
}
END {
    # Output results
    for (ext in count) {
        printf "%d %s\n", count[ext], ext
    }
}
' | \
sort -t ' ' -k1,1nr -k2,2 | \
awk '{
    # Extract extension (might be "(none)")
    ext = $2
    for (i = 3; i <= NF; i++) ext = ext " " $i
    printf "%s %d\n", ext, $1
}'
